Krieger k = new Krieger();
k.Name = "Thorin";
k.Ruestung = 5;
k.SchadenNehmen(30);      // geerbt von Figur
k.Status();               // geerbt von Figur
Console.WriteLine($"Rüstung: {k.Ruestung}");
// Ausgabe:
// Thorin: 70 Leben
// Rüstung: 5

class Figur
{
    public string Name { get; set; } = "";
    public int Leben { get; set; } = 100;

    public void SchadenNehmen(int schaden)
    {
        Leben -= schaden;
    }

    public void Status()
    {
        Console.WriteLine($"{Name}: {Leben} Leben");
    }
}

class Krieger : Figur
{
    public int Ruestung { get; set; }
}

Magier m = new Magier("Merlin", 50);
m.Zaubern();
m.Zaubern();
// Ausgabe:
// Figur Merlin wird erstellt.
// Magier wird erstellt.
// Merlin zaubert! Mana übrig: 30
// Merlin zaubert! Mana übrig: 10

class Figur
{
    public string Name { get; }

    public Figur(string name)
    {
        Name = name;
        Console.WriteLine($"Figur {name} wird erstellt.");
    }
}

class Magier : Figur
{
    public int Mana { get; private set; }

    public Magier(string name, int mana) : base(name)
    {
        Mana = mana;
        Console.WriteLine("Magier wird erstellt.");
    }

    public void Zaubern()
    {
        Mana -= 20;
        Console.WriteLine($"{Name} zaubert! Mana übrig: {Mana}");
    }
}

Sparkonto s = new Sparkonto();
s.Einzahlen(200);
s.ZinsenGutschreiben();
s.Anzeigen();
// s.guthaben = 1000;   // Fehler! protected ist von außen nicht sichtbar
// Ausgabe: Guthaben: 210 Euro

class Konto
{
    protected int guthaben;

    public void Einzahlen(int betrag)
    {
        guthaben += betrag;
    }

    public void Anzeigen()
    {
        Console.WriteLine($"Guthaben: {guthaben} Euro");
    }
}

class Sparkonto : Konto
{
    public void ZinsenGutschreiben()
    {
        guthaben += guthaben * 5 / 100;   // erlaubt dank protected
    }
}

